/* Aurora — midnight sky with drifting teal/violet light ribbons */
.theme-aurora {
  --bg: oklch(0.16 0.04 260);
  --surface: oklch(0.22 0.045 262 / 78%);
  --surface-2: oklch(0.27 0.05 264 / 82%);
  --fg: oklch(0.96 0.015 250);
  --fg-muted: oklch(0.76 0.03 250);
  --accent: oklch(0.79 0.16 175);
  --accent-fg: oklch(0.15 0.04 260);
  --accent-2: oklch(0.72 0.17 300);
  --line: oklch(0.79 0.16 175 / 26%);
  --success: oklch(0.79 0.16 165);
  --warning: oklch(0.83 0.15 88);
  --danger: oklch(0.68 0.2 18);

  --radius: 1rem;
  --radius-sm: 0.625rem;
  --radius-lg: 1.5rem;
  --radius-pill: 9999px;

  --shadow-1: 0 2px 12px -4px oklch(0 0 0 / 50%);
  --shadow-2: 0 18px 44px -18px oklch(0.5 0.16 265 / 70%);
  --shadow-3: 0 34px 80px -28px oklch(0.5 0.16 265 / 80%);
  --glow: 0 0 46px -10px oklch(0.79 0.16 175 / 60%);

  --border-width: 1px;
  --blur-amount: 14px;

  --font-display: "Outfit", "Inter", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: -0.025em;
  --label-transform: uppercase;
  --label-tracking: 0.14em;

  background-color: var(--bg);
  background-image:
    radial-gradient(70rem 34rem at 20% -12%, oklch(0.7 0.17 175 / 42%), transparent 62%),
    radial-gradient(60rem 40rem at 88% 6%, oklch(0.62 0.19 300 / 42%), transparent 62%),
    radial-gradient(80rem 36rem at 45% 108%, oklch(0.55 0.16 230 / 45%), transparent 65%);
  background-attachment: fixed;
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-aurora h1,
.theme-aurora h2,
.theme-aurora h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
  font-weight: 600;
}

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
